# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Scalar fused KL reduction kernel (fallback for unaligned or small N)
__global__ void kl_div_kernel_scalar(
    const float* __restrict__ predictions,
    const float* __restrict__ targets,
    float* __restrict__ output,
    int N
) {
    extern __shared__ float sdata[];

    float partial = 0.0f;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = idx; i < N; i += stride) {
        float t = __ldg(&targets[i]);
        float p = __ldg(&predictions[i]);
        if (t > 0.0f) {
            partial += t * (logf(t) - logf(fmaxf(p, 1e-10f)));
        }
    }

    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1)
        partial += __shfl_down_sync(mask, partial, offset);

    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;
    if (lane == 0) sdata[warp_id] = partial;
    __syncthreads();

    int num_warps = blockDim.x >> 5;
    if (threadIdx.x < num_warps) {
        float val = sdata[threadIdx.x];
        for (int offset = num_warps >> 1; offset > 0; offset >>= 1)
            val += __shfl_down_sync(mask, val, offset);
        if (threadIdx.x == 0)
            atomicAdd(output, val);
    }
}

// Vectorized float4 fused KL reduction kernel
__global__ void __launch_bounds__(256, 4) kl_div_kernel_vec4(
    const float4* __restrict__ predictions4,
    const float4* __restrict__ targets4,
    float* __restrict__ output,
    int N4,       // number of float4 elements
    int N_tail,   // remaining scalar elements after the vectorized portion
    const float* __restrict__ pred_tail,
    const float* __restrict__ tgt_tail
) {
    extern __shared__ float sdata[];

    float partial = 0.0f;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Vectorized loop over float4 packs
    for (int i = idx; i < N4; i += stride) {
        float4 p4 = __ldg(&predictions4[i]);
        float4 t4 = __ldg(&targets4[i]);

        if (t4.x > 0.0f) partial += t4.x * (logf(t4.x) - logf(fmaxf(p4.x, 1e-10f)));
        if (t4.y > 0.0f) partial += t4.y * (logf(t4.y) - logf(fmaxf(p4.y, 1e-10f)));
        if (t4.z > 0.0f) partial += t4.z * (logf(t4.z) - logf(fmaxf(p4.z, 1e-10f)));
        if (t4.w > 0.0f) partial += t4.w * (logf(t4.w) - logf(fmaxf(p4.w, 1e-10f)));
    }

    // Tail elements handled by thread 0 of block 0
    if (blockIdx.x == 0 && threadIdx.x == 0) {
        for (int i = 0; i < N_tail; i++) {
            float t = tgt_tail[i];
            float p = pred_tail[i];
            if (t > 0.0f)
                partial += t * (logf(t) - logf(fmaxf(p, 1e-10f)));
        }
    }

    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1)
        partial += __shfl_down_sync(mask, partial, offset);

    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;
    if (lane == 0) sdata[warp_id] = partial;
    __syncthreads();

    int num_warps = blockDim.x >> 5;
    if (threadIdx.x < num_warps) {
        float val = sdata[threadIdx.x];
        for (int offset = num_warps >> 1; offset > 0; offset >>= 1)
            val += __shfl_down_sync(mask, val, offset);
        if (threadIdx.x == 0)
            atomicAdd(output, val);
    }
}

torch::Tensor kl_div_forward(torch::Tensor predictions, torch::Tensor targets) {
    TORCH_CHECK(predictions.is_cuda(), "predictions must be a CUDA tensor");
    TORCH_CHECK(targets.is_cuda(), "targets must be a CUDA tensor");
    TORCH_CHECK(predictions.scalar_type() == torch::kFloat32, "predictions must be float32");
    TORCH_CHECK(targets.scalar_type() == torch::kFloat32, "targets must be float32");

    auto pred_c = predictions.contiguous();
    auto tgt_c  = targets.contiguous();

    int N = (int)pred_c.numel();
    int batch_size = (int)pred_c.size(0);

    auto output = torch::zeros({1}, pred_c.options());

    const int block_size = 256;
    int num_warps = block_size / 32;
    int smem = num_warps * sizeof(float);

    const float* pred_ptr = pred_c.data_ptr<float>();
    const float* tgt_ptr  = tgt_c.data_ptr<float>();

    bool aligned = (reinterpret_cast<uintptr_t>(pred_ptr) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(tgt_ptr)  % 16 == 0);

    if (aligned && N >= 4) {
        int N4     = N / 4;
        int N_tail = N % 4;
        int grid_size = std::min((N4 + block_size - 1) / block_size, 2048);

        kl_div_kernel_vec4<<<grid_size, block_size, smem>>>(
            reinterpret_cast<const float4*>(pred_ptr),
            reinterpret_cast<const float4*>(tgt_ptr),
            output.data_ptr<float>(),
            N4,
            N_tail,
            pred_ptr + N4 * 4,
            tgt_ptr  + N4 * 4
        );
    } else {
        int grid_size = std::min((N + block_size - 1) / block_size, 2048);
        kl_div_kernel_scalar<<<grid_size, block_size, smem>>>(
            pred_ptr,
            tgt_ptr,
            output.data_ptr<float>(),
            N
        );
    }

    return output / (float)batch_size;
}
# <<<END_IMPROVE>>>
